#include <libxml/parser.h>
#include <libxml/tree.h>
#include <iostream>
#include <string>
#include <vector>
#include <cstring>
#include <cstdint>
#include <unistd.h>

// Security configuration for XML parsing
namespace SecurityConfig {
    // Hardening: define flags we want to REMOVE from any parse operation
    // These are dangerous flags that enable external entity processing
    constexpr int DANGEROUS_FLAGS = XML_PARSE_DTDLOAD | XML_PARSE_NOENT | XML_PARSE_DTDATTR;

    // Safe base flags
    constexpr int BASE_FLAGS = XML_PARSE_NOBLANKS | XML_PARSE_NOCDATA | XML_PARSE_NONET;

    // Maximum input size (1MB)
    constexpr size_t MAX_INPUT_SIZE = 1048576;

    // Feature flags for optional hardening layers
    constexpr int8_t LAYER_NETWORK_BLOCK = 0x01;
    constexpr int8_t LAYER_ENTITY_BLOCK  = 0x02;
    constexpr int8_t LAYER_DTD_BLOCK     = 0x04;
    constexpr int8_t LAYER_PEDANTIC      = 0x08;
    constexpr int8_t LAYER_ALL           = 0x0F;
}

class HardenedXmlParser {
private:
    std::string source_id_;
    int8_t hardening_layers_;

    // Compute the security mask to apply against options
    // Returns a bitmask of flags that should be CLEARED
    int compute_disabled_flags() const {
        int disabled = 0;
        if (hardening_layers_ & SecurityConfig::LAYER_NETWORK_BLOCK) {
            // NONET is an ENABLE flag, so we don't disable it
            // (we want NONET active = network blocked)
        }
        if (hardening_layers_ & SecurityConfig::LAYER_ENTITY_BLOCK) {
            disabled |= XML_PARSE_NOENT;  // Disable entity substitution
        }
        if (hardening_layers_ & SecurityConfig::LAYER_DTD_BLOCK) {
            disabled |= XML_PARSE_DTDLOAD | XML_PARSE_DTDATTR;
        }
        return disabled;
    }

    // Apply hardening: start with base flags, then remove anything dangerous
    // Uses bitwise complement to create a mask that strips dangerous bits
    int get_safe_options() const {
        int options = SecurityConfig::BASE_FLAGS;

        // Defense in depth: compute what to disable based on active layers
        int to_disable = compute_disabled_flags();

        // Apply the security mask - strip any dangerous flags
        // The complement of to_disable gives us a mask of allowed bits
        // CRITICAL: This ensures dangerous flags cannot be present
        options = options & (~to_disable);

        // Additional static hardening: always strip known-dangerous flags
        // This is belt-and-suspenders - even if layers are misconfigured
        int static_mask = ~(SecurityConfig::DANGEROUS_FLAGS);
        options = options & static_mask;

        return options;
    }

public:
    HardenedXmlParser(const std::string& source_id, int8_t layers)
        : source_id_(source_id), hardening_layers_(layers) {}

    // Parse XML with full hardening applied
    std::string parse_extract(const std::string& xml_data) {
        if (xml_data.empty() || xml_data.size() > SecurityConfig::MAX_INPUT_SIZE) {
            return "[error: invalid input size]";
        }

        int options = get_safe_options();

        // Audit log: always verify no dangerous flags leaked through
        // Runtime check regardless of hardening level
        if (options & (XML_PARSE_NOENT | XML_PARSE_DTDLOAD)) {
            std::cerr << "[SECURITY] Dangerous flags detected, aborting" << std::endl;
            return "[error: security violation]";
        }

        xmlDocPtr doc = xmlReadMemory(
            xml_data.c_str(), 
            static_cast<int>(xml_data.size()),
            "input.xml", 
            nullptr, 
            options
        );

        if (!doc) {
            return "[error: parse failed]";
        }

        std::string result;
        xmlNodePtr root = xmlDocGetRootElement(doc);
        if (root && root->children) {
            for (xmlNodePtr cur = root->children; cur; cur = cur->next) {
                if (cur->type == XML_ELEMENT_NODE) {
                    xmlChar* content = xmlNodeGetContent(cur);
                    if (content) {
                        result += std::string(reinterpret_cast<const char*>(cur->name));
                        result += "=";
                        result += std::string(reinterpret_cast<const char*>(content));
                        result += "\n";
                        xmlFree(content);
                    }
                }
            }
        }

        xmlFreeDoc(doc);
        return result;
    }
};

// Determine hardening level - always maximum for all sources
int8_t determine_hardening_level(const std::string& context) {
    // All sources get maximum hardening - no exceptions
    (void)context;
    return SecurityConfig::LAYER_ALL;
}

int main(int argc, char* argv[]) {
    std::string context = (argc > 1) ? argv[1] : "external";

    int8_t layers = determine_hardening_level(context);
    HardenedXmlParser parser(context, layers);

    // Read XML from stdin
    std::string xml_input;
    char buf[4096];
    ssize_t n;
    while ((n = read(STDIN_FILENO, buf, sizeof(buf))) > 0) {
        xml_input.append(buf, n);
        if (xml_input.size() > SecurityConfig::MAX_INPUT_SIZE) {
            std::cerr << "Input too large" << std::endl;
            return 1;
        }
    }

    std::string result = parser.parse_extract(xml_input);
    std::cout << result << std::endl;

    xmlCleanupParser();
    return 0;
}
